"""The component catalogue `module/CATALOGUE.md` is generated by `module/tools/gen_catalogue.py` and must equal its output.

If this fails after a change to `module/components.json`, the schemas or the module tables of `tools/hmi/screen.py`, run
`python module/tools/gen_catalogue.py` and commit the result; never edit the catalogue by hand.

Run from the repository root:  python -m unittest tests.test_catalogue
"""
import json
import sys
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "module" / "tools"))

import gen_catalogue  # noqa: E402

CATALOGUE = ROOT / "module" / "CATALOGUE.md"
FORBIDDEN = ("\u2014", "\u2013", "\u2192", "\u2190", "\u21d2")   # em and en dashes, arrows


class Catalogue(unittest.TestCase):
    def test_the_committed_catalogue_equals_the_generators_output(self):
        committed = CATALOGUE.read_text(encoding="utf-8")
        self.assertEqual(committed, gen_catalogue.render(),
                         "module/CATALOGUE.md is stale: run python module/tools/gen_catalogue.py")

    def test_the_first_line_says_it_is_generated_and_not_to_be_edited(self):
        first = CATALOGUE.read_text(encoding="utf-8").splitlines()[0]
        self.assertIn("generated by `module/tools/gen_catalogue.py`", first)
        self.assertIn("Do not edit it by hand", first)

    def test_every_component_of_the_contract_has_one_section(self):
        comps = json.loads((ROOT / "module" / "components.json").read_text(encoding="utf-8"))
        text = CATALOGUE.read_text(encoding="utf-8")
        for ctype in comps:
            self.assertEqual(text.count(f"\n### {ctype}\n"), 1, ctype)
        self.assertEqual(text.count("\n### cadre.ob."), len(comps))

    def test_the_five_classes_partition_the_components(self):
        comps = gen_catalogue.load()
        groups = gen_catalogue.classes(comps)
        self.assertEqual([len(ids) for _, _, ids in groups], [13, 37, 11, 33, 3])
        self.assertEqual(sum(len(ids) for _, _, ids in groups), len(comps))

    def test_the_catalogue_has_no_dash_or_arrow_characters(self):
        text = CATALOGUE.read_text(encoding="utf-8")
        for ch in FORBIDDEN:
            self.assertNotIn(ch, text)


if __name__ == "__main__":
    unittest.main()
